(WOOD, WOODDARK, BRASS, CREAM, VELVET, LEATHER, IRON, GLASS, LINEN, PORCELAIN, SILVER, SHADE) = set_palette([
    ("Trn_Wood",       (0.45, 0.24, 0.12), 0.0, 0.6, {"tex": "wood", "tile": 2.0, "planks": 1, "rings": 14, "seams": False}),
    ("Trn_WoodDark",   (0.20, 0.10, 0.05), 0.0, 0.6, {"tex": "wood", "tile": 1.0, "planks": 2}),
    ("Trn_Brass",      (0.95, 0.70, 0.25), 1.0, 0.3, {"tex": "brushed", "tile": 0.5}),
    ("Trn_Cream",      (0.90, 0.84, 0.68), 0.0, 0.8, {"tex": "plaster", "tile": 2.0}),
    ("Trn_Velvet",     (0.45, 0.07, 0.10), 0.0, 0.9, {"tex": "velvet", "tile": 0.5}),
    ("Trn_Leather",    (0.40, 0.22, 0.10), 0.0, 0.7, {"tex": "leather", "tile": 0.5}),
    ("Trn_Iron",       (0.18, 0.20, 0.22), 0.6, 0.5, {"tex": "painted_metal", "tile": 2.0}),
    ("Trn_Glass",      (0.05, 0.08, 0.07), 0.0, 0.1),
    # new for the dining car
    ("Trn_Linen",      (0.48, 0.39, 0.26), 0.0, 1.0, {"tex": "fabric", "tile": 0.5}),  # warm oatmeal (sRGB ~ #B8A88C), matt: the plates stand out
    ("Trn_Porcelain",  (0.93, 0.92, 0.88), 0.0, 0.25, {"tex": "plain", "tile": 0.5}),
    ("Trn_Silver",     (0.80, 0.80, 0.82), 1.0, 0.3),                                   # cutlery
    ("Trn_Shade",      (0.03, 0.16, 0.07), 0.0, 0.6)])                                  # lamp shades: dark green, smooth, matt, untextured


# ---------------------------------------------------------------- Unity-axis helpers
# u = Unity local x, w = Unity local z, y = height. Blender point = (-u, -w, y).
def R(mb, u0, u1, w0, w1, y0, y1, slot):
    mb.rect(-u1, -u0, -w1, -w0, y0, y1, slot)


def L(mb, profile, u, w, slot, segs=24, **kw):
    """Lathe (radius, height) around a vertical axis at Unity (u, w)."""
    mb.lathe(profile, segs=segs, slot=slot, center=(-u, -w, 0.0), **kw)


def tube_u(mb, u0, u1, w, y, r, slot, segs=10):
    """Horizontal tube along Unity x."""
    mb.lathe([(r, 0.0), (r, u1 - u0)], segs=segs, slot=slot, center=(-u0, -w, y),
             mat3=Matrix.Rotation(radians(-90), 3, 'Y'))


def tube_w(mb, w0, w1, u, y, r, slot, segs=10):
    """Horizontal tube along Unity z."""
    mb.lathe([(r, 0.0), (r, w1 - w0)], segs=segs, slot=slot, center=(-u, -w0, y),
             mat3=Matrix.Rotation(radians(90), 3, 'X'))


def box_f(mb, ou, ow, fu, fw, f0, f1, s0, s1, y0, y1, slot):
    """Box in a chair's frame: f along the facing (fu, fw) (cardinal), s across it."""
    su, sw = fw, -fu
    us = [ou + fu * f + su * s for f in (f0, f1) for s in (s0, s1)]
    ws = [ow + fw * f + sw * s for f in (f0, f1) for s in (s0, s1)]
    R(mb, min(us), max(us), min(ws), max(ws), y0, y1, slot)


def chair(mb, ou, ow, fu, fw):
    """Dining chair, its seat centre at (ou, ow), the sitter facing (fu, fw): wood frame, velvet seat
    and back pad. Seat 0.42 square, top 0.47; back 0.95. Footprint: f -0.24..0.21, s -0.21..0.21."""
    for f in (-0.19, 0.17):
        for s in (-0.18, 0.18):
            box_f(mb, ou, ow, fu, fw, f - 0.02, f + 0.02, s - 0.02, s + 0.02, 0.0, 0.42, WOODDARK)
    box_f(mb, ou, ow, fu, fw, -0.21, 0.21, -0.21, 0.21, 0.42, 0.44, WOODDARK)       # seat board
    box_f(mb, ou, ow, fu, fw, -0.19, 0.19, -0.19, 0.19, 0.44, 0.47, VELVET)         # cushion
    box_f(mb, ou, ow, fu, fw, -0.24, -0.19, -0.2, 0.2, 0.44, 0.95, WOODDARK)        # back
    box_f(mb, ou, ow, fu, fw, -0.19, -0.17, -0.16, 0.16, 0.56, 0.88, VELVET)        # back pad


def lamp(mb, u, w, y):
    """Brass table lamp with a cream shade, standing at height y."""
    L(mb, [(0.06, y), (0.06, y + 0.015), (0.02, y + 0.03)], u, w, BRASS, segs=16, cap_top=False)
    L(mb, [(0.008, y + 0.03), (0.008, y + 0.26)], u, w, BRASS, segs=8)
    # the shade: a solid ring (6 mm wall), so it reads from inside and out, from any side
    L(mb, [(0.10, y + 0.2), (0.05, y + 0.34), (0.044, y + 0.34), (0.094, y + 0.2)], u, w, SHADE, segs=24, closed=True)
    L(mb, [(0.02, y + 0.235), (0.02, y + 0.255)], u, w, SHADE, segs=8)                 # bulb hidden inside


def flat(mb, ou, ow, fu, fw, pts, y0, y1, slot):
    """A flat piece lying on the table: polygon `pts` in the setting's frame (f along the facing, s to the sitter's
    right), from height y0 to y1. Convex outlines only (fan-triangulated)."""
    su, sw = fw, -fu
    ring = [(-(ou + fu * f + su * s), -(ow + fw * f + sw * s)) for f, s in pts]   # Blender (x, y)
    n = len(ring)
    verts = [(x, y, y0) for x, y in ring] + [(x, y, y1) for x, y in ring]
    faces = [list(reversed(range(n))), list(range(n, 2 * n))]
    faces += [[i, (i + 1) % n, n + (i + 1) % n, n + i] for i in range(n)]
    mb.add(verts, faces, slot)


def knife(mb, ou, ow, fu, fw, y):
    """Table knife, blade away from the sitter: a rounded handle and a blade with a curved spine and round tip."""
    flat(mb, ou, ow, fu, fw, [(-0.1, -0.008), (-0.1, 0.008), (-0.098, 0.0095), (-0.03, 0.0085), (-0.027, 0.0),
                              (-0.03, -0.0085), (-0.098, -0.0095)], y, y + 0.007, SILVER)
    flat(mb, ou, ow, fu, fw, [(-0.027, -0.006), (-0.027, 0.0075), (0.04, 0.008), (0.065, 0.006), (0.075, 0.002),
                              (0.077, -0.002), (0.07, -0.006)], y, y + 0.0025, SILVER)


def fork(mb, ou, ow, fu, fw, y):
    """Table fork, tines away from the sitter: handle, a neck widening into the head, four tines."""
    flat(mb, ou, ow, fu, fw, [(-0.1, -0.008), (-0.1, 0.008), (-0.098, 0.0095), (-0.025, 0.0065), (-0.02, 0.004),
                              (-0.02, -0.004), (-0.025, -0.0065), (-0.098, -0.0095)], y, y + 0.006, SILVER)
    flat(mb, ou, ow, fu, fw, [(-0.02, -0.004), (-0.02, 0.004), (0.015, 0.012), (0.03, 0.012), (0.03, -0.012),
                              (0.015, -0.012)], y, y + 0.003, SILVER)
    for k in range(4):
        s = -0.0105 + k * 0.007
        flat(mb, ou, ow, fu, fw, [(0.03, s - 0.0018), (0.03, s + 0.0018), (0.068, s + 0.0014), (0.07, s),
                                  (0.068, s - 0.0014)], y, y + 0.003, SILVER)


def setting(mb, u, w, fu, fw, y):
    """A place setting in front of a chair facing (fu, fw): a rimmed dinner plate, the fork to its left and the
    knife to its right, the cup and saucer above the knife, clear of the plate (cup centre 21 cm from the plate's)."""
    pu, pw = u + fu * 0.2, w + fw * 0.2
    su, sw = fw, -fu                                                   # to the sitter's right
    L(mb, [(0.07, y), (0.075, y + 0.006), (0.115, y + 0.012), (0.12, y + 0.02), (0.112, y + 0.02),
           (0.07, y + 0.012), (0.0, y + 0.012)], pu, pw, PORCELAIN, segs=28)
    fork(mb, pu - su * 0.155, pw - sw * 0.155, fu, fw, y)
    knife(mb, pu + su * 0.155, pw + sw * 0.155, fu, fw, y)
    cu, cw = pu + fu * 0.15 + su * 0.15, pw + fw * 0.15 + sw * 0.15
    L(mb, [(0.03, y), (0.048, y + 0.004), (0.055, y + 0.01), (0.05, y + 0.01), (0.0, y + 0.006)],
      cu, cw, PORCELAIN, segs=20)                                      # saucer
    L(mb, [(0.022, y + 0.008), (0.03, y + 0.016), (0.036, y + 0.06), (0.032, y + 0.06), (0.0, y + 0.018)],
      cu, cw, PORCELAIN, segs=20)                                      # cup
    hu, hw = cu + su * 0.042, cw + sw * 0.042                          # its handle, on the right
    box_f(mb, hu, hw, fu, fw, -0.004, 0.004, -0.008, 0.008, y + 0.025, y + 0.05, PORCELAIN)


def pedestal(mb, u, w, top):
    L(mb, [(0.25, 0.0), (0.25, 0.03), (0.08, 0.06)], u, w, WOODDARK, segs=20, cap_top=False)
    L(mb, [(0.045, 0.06), (0.045, top)], u, w, WOODDARK, segs=12)


def square_table(name, tiles, chairs, settings=True, lamps=None):
    """Tables made of 1 m tiles (Unity (u, w) tile centres, the pivot tile first): a dark wood top per tile
    under one linen cloth, a pedestal per tile, the cloth hanging 12 cm on the outside edges."""
    a = Asset(name, seed=SEED)
    S, P = a.S, a.P
    H = TABLE_HEIGHT
    cells = set(tiles)
    e = 0.45                                         # the top's half size (5 cm in from the tile edge)
    for (u, w) in tiles:
        # Grow the top to the neighbouring table tile, so the cloth is one sheet (abutting boxes).
        u0 = u - (0.5 if (u - 1, w) in cells else e)
        u1 = u + (0.5 if (u + 1, w) in cells else e)
        w0 = w - (0.5 if (u, w - 1) in cells else e)
        w1 = w + (0.5 if (u, w + 1) in cells else e)
        R(S, u0, u1, w0, w1, H - 0.045, H - 0.005, WOODDARK)
        R(S, u0 - 0.005, u1 + 0.005, w0 - 0.005, w1 + 0.005, H - 0.005, H, LINEN)
        pedestal(S, u, w, H - 0.045)
        # cloth drop on the free edges (5 mm outside the top, its own depth)
        for (du, dw) in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            if (u + du, w + dw) in cells:
                continue
            if du:
                x = u + du * (e + 0.005)
                R(S, min(x, x + du * 0.006), max(x, x + du * 0.006), w0 - 0.011, w1 + 0.011, H - 0.13, H, LINEN)
            else:
                z = w + dw * (e + 0.005)
                R(S, u0 - 0.005, u1 + 0.005, min(z, z + dw * 0.006), max(z, z + dw * 0.006), H - 0.13, H - 0.001, LINEN)
    for (u, w, fu, fw) in chairs:
        chair(P, u, w, fu, fw)
        if settings:
            setting(P, u - fu * 0.04, w - fw * 0.04, fu, fw, H)   # the plate 0.26 in from the table edge side, wherever the chair is
    for (u, w) in (lamps or tiles[:1]):
        lamp(P, u, w, H)
        a.anchors.append((-u, -w, H + 0.25))          # the bulb: the game may light it
    return a.finish(anchors=True)


def table_1():
    return square_table("Dining_Table_1", [(0, 0)], [(-0.42, 0, 1, 0), (0.42, 0, -1, 0)])


def table_2():
    return square_table("Dining_Table_2", [(0, 0), (1, 0)], [(-0.42, 0, 1, 0), (1.42, 0, -1, 0)], lamps=[(0.5, 0)])


def table_l():
    # corner (0,0), arms (1,0) and (0,-1); chairs at the arm ends and inside the arms, facing out of the corner
    tiles = [(0, 0), (1, 0), (0, -1)]
    chairs = [(1.42, 0, -1, 0), (0, -1.42, 0, 1), (0.95, -0.42, 0, 1), (0.42, -0.95, -1, 0)]
    return square_table("Dining_Table_L", tiles, chairs, lamps=[(0, 0)])


def table_round():
    a = Asset("Dining_Table_Round", seed=SEED)
    S, P = a.S, a.P
    H, r = TABLE_HEIGHT, 0.66
    L(S, [(0.32, 0.0), (0.32, 0.035), (0.1, 0.07)], 0, 0, WOODDARK, segs=28, cap_top=False)
    L(S, [(0.06, 0.07), (0.06, H - 0.045)], 0, 0, WOODDARK, segs=14)
    L(S, [(r - 0.01, H - 0.045), (r - 0.01, H - 0.005)], 0, 0, WOODDARK, segs=48)
    L(S, [(r, H - 0.005), (r, H)], 0, 0, LINEN, segs=48)
    L(S, [(r + 0.005, H - 0.001), (r + 0.012, H - 0.14)], 0, 0, LINEN, segs=48, cap_bottom=False, cap_top=False)  # drop
    for (fu, fw) in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        cu, cw = -fu * 0.66, -fw * 0.66
        chair(P, cu, cw, fu, fw)
        setting(P, -fu * 0.48, -fw * 0.48, fu, fw, H)
    lamp(P, 0, 0, H)
    a.anchors.append((0.0, 0.0, H + 0.25))
    return a.finish(anchors=True)


def cart():
    a = Asset("Dining_Cart", seed=SEED)
    S, P = a.S, a.P
    U, W = 0.40, 0.21                                 # post positions
    for u in (-U, U):
        for w in (-W, W):
            L(S, [(0.012, 0.09), (0.012, 0.86)], u, w, BRASS, segs=10)
            # wheel: a dark disc on an axle along z
            tube_w(S, w - 0.012, w + 0.012, u, 0.05, 0.05, IRON, segs=16)
            L(S, [(0.016, 0.075), (0.016, 0.09)], u, w, BRASS, segs=8)          # fork
    for y in (0.28, 0.82):                                                    # two trays with brass lips
        R(S, -0.43, 0.43, -0.24, 0.24, y, y + 0.03, WOODDARK)
        for w in (-0.245, 0.235):
            R(S, -0.43, 0.43, w, w + 0.01, y + 0.03, y + 0.07, BRASS)
        for u in (-0.435, 0.425):
            R(S, u, u + 0.01, -0.235, 0.235, y + 0.03, y + 0.07, BRASS)
    # push handle at +X
    for w in (-W, W):
        tube_u(S, U, U + 0.08, w, 0.9, 0.011, BRASS)
        L(S, [(0.011, 0.86), (0.011, 0.9)], U, w, BRASS, segs=8)
    tube_w(S, -W - 0.03, W + 0.03, U + 0.08, 0.9, 0.016, LEATHER, segs=12)
    # on top: teapot, two cups, a cloche; below: a stack of plates and a wine bottle
    top = 0.85
    L(P, [(0.04, top), (0.075, top + 0.03), (0.08, top + 0.07), (0.06, top + 0.11), (0.02, top + 0.125),
          (0.012, top + 0.145)], -0.22, 0.0, PORCELAIN, segs=20)
    tube_u(P, -0.16, -0.09, 0.0, top + 0.06, 0.008, PORCELAIN, segs=8)                      # spout
    for (u, w) in ((-0.02, 0.1), (0.07, -0.1)):
        L(P, [(0.05, top), (0.05, top + 0.006)], u, w, PORCELAIN, segs=14)
        L(P, [(0.028, top + 0.006), (0.036, top + 0.06)], u, w, PORCELAIN, segs=14)
    L(P, [(0.13, top), (0.13, top + 0.01)], 0.26, 0.05, PORCELAIN, segs=20)
    L(P, [(0.12, top + 0.01), (0.1, top + 0.08), (0.05, top + 0.12), (0.0, top + 0.13)], 0.26, 0.05, BRASS,
      segs=20, cap_top=False)
    L(P, [(0.012, top + 0.13), (0.012, top + 0.16)], 0.26, 0.05, BRASS, segs=8)
    low = 0.31
    for i in range(5):
        L(P, [(0.1, low + i * 0.014), (0.11, low + i * 0.014 + 0.012)], -0.2, 0.0, PORCELAIN, segs=20)
    L(P, [(0.035, low), (0.035, low + 0.2), (0.012, low + 0.26), (0.012, low + 0.3)], 0.2, 0.05, GLASS, segs=14)
    return a.finish()


def bar_l():
    """A normal bar: the counter stands out in the room (4 tiles along +X from the corner tile at the pivot), its
    front and foot rail facing the room (-Z); the short leg runs from the corner back to the wall (1 tile along +Z,
    the wall's inner face at w = 1.5). The bartender stands behind it, between the counter and a back shelf on the
    wall (both inside the L's tiles' row and the row behind)."""
    a = Asset("Bar_L", seed=SEED)
    S, P = a.S, a.P
    top = 1.06
    front, back = -0.25, 0.3                          # the counter's body, across (w)
    left, inner = -0.45, 0.18                         # the short leg's body, along (u)
    end, wall = 3.45, 1.45                            # the counter's far end; the short leg stops at the wall
    # bodies: the counter full length, the short leg fitted behind it (corners: no overlap)
    R(S, left, end, front, back, 0.0, top, WOOD)
    R(S, left, inner, back, wall, 0.0, top, WOOD)
    # kick plates (proud 1 cm, start 4 mm up) on the room faces: the front, the corner's end, the leg's outer side
    R(S, left - 0.01, end, front - 0.01, front, 0.004, 0.12, WOODDARK)
    R(S, end, end + 0.01, front - 0.01, back, 0.004, 0.12, WOODDARK)
    R(S, left - 0.01, left, front, wall, 0.004, 0.12, WOODDARK)
    # raised panels: six along the front, two down the leg's outer side, one on the far end
    span = (end - left) / 6
    for i in range(6):
        u0 = left + i * span
        R(S, u0 + 0.06, u0 + span - 0.06, front - 0.02, front, 0.22, top - 0.14, WOODDARK)
    for (w0, w1) in ((front + 0.08, back + 0.5), (back + 0.6, wall - 0.08)):
        R(S, left - 0.02, left, w0, w1, 0.22, top - 0.14, WOODDARK)
    R(S, end, end + 0.02, front + 0.08, back - 0.08, 0.22, top - 0.14, WOODDARK)
    # the bartender's side: a dark plain back with an under-counter shelf
    R(S, inner, end, back, back + 0.01, 0.004, top - 0.02, WOODDARK)
    R(S, inner + 0.01, end - 0.05, back + 0.01, back + 0.25, 0.45, 0.48, WOODDARK)
    # counter top: one slab along the counter, one on the leg (abutting), overhanging the room side
    R(S, left - 0.1, end + 0.08, front - 0.1, back + 0.03, top, top + 0.05, WOODDARK)
    R(S, left - 0.1, inner + 0.03, back + 0.03, wall - 0.01, top, top + 0.05, WOODDARK)
    R(S, left - 0.1, end + 0.08, front - 0.105, front - 0.1, top + 0.005, top + 0.045, BRASS)    # brass edge strip
    # brass foot rail round the room side: along the front and down the leg's outer side, on brackets
    rw, ru = front - 0.14, left - 0.14
    tube_u(S, ru, end - 0.05, rw, 0.17, 0.022, BRASS, segs=12)
    tube_w(S, rw, wall - 0.08, ru, 0.17, 0.022, BRASS, segs=12)
    L(S, [(0.026, 0.17 - 0.026), (0.026, 0.17 + 0.026)], ru, rw, BRASS, segs=12)              # corner knuckle
    for u in (0.6, 1.6, 2.6):
        R(S, u - 0.015, u + 0.015, rw + 0.02, front - 0.01, 0.15, 0.19, BRASS)
    for w in (0.4, 1.1):
        R(S, ru + 0.02, left - 0.01, w - 0.015, w + 0.015, 0.15, 0.19, BRASS)
    # the back shelf on the wall behind the bartender: a low cupboard and two shelves of bottles
    sb0, sb1 = 1.22, 1.45
    R(S, inner + 0.3, end, sb0, sb1, 0.0, 0.9, WOODDARK)
    R(S, inner + 0.3, end, sb0 - 0.02, sb1, 0.9, 0.94, WOOD)
    R(S, inner + 0.3, end, sb0 + 0.06, sb1, 1.35, 1.38, WOOD)                               # one shelf: wall lamps go above
    for u in (inner + 0.31, end - 0.03):
        R(S, u - 0.01, u + 0.02, sb0 + 0.06, sb1, 0.94, 1.7, WOOD)                           # shelf ends
    rng = a.rng
    for y in (0.94, 1.38):
        u = inner + 0.42
        while u < end - 0.12:
            h = rng.uniform(0.2, 0.3)
            L(P, [(0.03, y), (0.03, y + h), (0.011, y + h + 0.06), (0.011, y + h + 0.09)], u, sb0 + 0.14, GLASS, segs=10)
            u += rng.uniform(0.1, 0.17)
    # on the counter: beer taps facing the bartender, a cash register at the far end, glasses, a bottle or two
    ty = top + 0.05
    for u in (1.2, 1.45):
        R(P, u - 0.03, u + 0.03, back - 0.12, back - 0.04, ty, ty + 0.03, BRASS)
        L(P, [(0.018, ty + 0.03), (0.018, ty + 0.3)], u, back - 0.08, BRASS, segs=10)
        tube_w(P, back - 0.08, back + 0.06, u, ty + 0.28, 0.012, BRASS, segs=8)
        L(P, [(0.014, ty + 0.2), (0.014, ty + 0.28)], u, back + 0.06, BRASS, segs=8)
        L(P, [(0.02, ty + 0.3), (0.02, ty + 0.42)], u, back - 0.08, WOODDARK, segs=10)          # handle
    R(P, 2.95, 3.35, -0.02, 0.28, ty, ty + 0.18, BRASS)                                       # register, keys to the back
    R(P, 3.0, 3.3, -0.02, 0.18, ty + 0.18, ty + 0.3, BRASS)
    for (u, w) in ((2.1, -0.12), (2.3, -0.16), (2.45, -0.1), (0.3, -0.14), (-0.2, 0.7), (-0.05, 1.0)):
        L(P, [(0.03, ty), (0.035, ty + 0.11)], u, w, GLASS, segs=12, cap_top=False)
    for u in (0.55, 0.68):
        L(P, [(0.032, ty), (0.032, ty + 0.26), (0.011, ty + 0.32), (0.011, ty + 0.36)], u, 0.1, GLASS, segs=12)
    return a.finish()


run([table_1, table_2, table_l, table_round, cart, bar_l], spacing=4.0)
